{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city.",
      "visual_description": "A broken royal gate looms under a grey sky, rubble and faded banners scattered. The glass diver stands at the threshold, helmet reflecting the shattered city.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unfolds a map on a fallen pillar.",
      "visual_description": "Mara spreads a worn map across a cracked stone pillar, her brass compass catching a sliver of light. The tin fox sniffs at the edges.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "A twisted tower flickers with green light as the oracle lamp's flame-eye glows, casting shadows on a broken street.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "Sleeping tax collector snores behind a collapsed wall.",
      "visual_description": "A dozing figure lies amid stamped papers and a ledger book pillow, with an armored patrol clanking past in the distance.",
      "characters": ["sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Tin fox scouts the castle gates.",
      "visual_description": "The small metal fox creeps over a fallen portcullis, blue glass eyes scanning for danger. Old royal banners flutter from a broken tower.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "Glass diver dives through a window into a guarded courtyard.",
      "visual_description": "The glass diver steps through a cracked window pane, emerging in a courtyard filled with armored patrols. His coat reflects the torchlight.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "Mara marks a secret passage on her map.",
      "visual_description": "Mara inks a winding line into her map, the tin fox pointing with its nose toward a hidden door behind rubble.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Oracle lamp reveals a magic door behind a tapestry.",
      "visual_description": "The lamp's glow illuminates a faded tapestry. Behind it, a door pulses with runes. Glass diver approaches cautiously.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Sleeping tax collector is carried through a mirror.",
      "visual_description": "Glass diver hoists the snoring collector through a large mirror, the portal rippling. Mara and tin fox follow with the map.",
      "characters": ["glass_diver", "sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Tin fox decoys an armored patrol near a fountain.",
      "visual_description": "The clockwork fox winds its tail and skitters across a plaza, drawing clanking patrols away from a crumbling fountain. Glass diver hides behind it.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Mara finds a safe route on a broken aqueduct.",
      "visual_description": "Mara climbs a fallen aqueduct, compass in hand, pointing toward a distant bridge. Oracle lamp warns of unstable stones.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "Glass diver swims through a reflecting pool to reach a locked door.",
      "visual_description": "The glass diver plunges into a murky pool, surface shattering like glass as he emerges inside a tower chamber with a locked door.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Sleeping tax collector wakes briefly, mumbles about tolls.",
      "visual_description": "The tax collector stirs, blinking at the ruined hall, then drifts off again, a stamped paper sliding from his sleeve. Glass diver rolls his eyes.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "Oracle lamp deciphers a riddle on a cursed door.",
      "visual_description": "The lamp's flame eye glows as it reads ancient runes on a bronze door. Mara transcribes the answer onto her map.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "Glass diver shatters a mirror to create an exit.",
      "visual_description": "Glass diver strikes a large mirror with his helmet, sending shards flying. Beyond lies a moonlit street leading to the bridge.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The group crosses a ruined bridge under pursuit.",
      "visual_description": "The bridge groans over a deep chasm as armored patrols march onto it from the city. Glass diver carries the sleeping tax collector.",
      "characters": ["glass_diver", "sleeping_tax_collector", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "Mara cuts the bridge ropes to slow the patrols.",
      "visual_description": "Mara slices a rope with her compass edge; the bridge begins to collapse. The tin fox pulls her back as the patrols fall.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes into the hills as the city burns.",
      "visual_description": "On a grassy hill, the glass diver, Mara, tin fox, oracle lamp, and sleeping tax collector watch the ruined city glow. Dawn breaks over the horizon.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

